import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address ownerCandidate) public {
        // The deployer is address(this), so owner() must equal address(this) in the reference.
        // The mutant replaces owner() with address(this) which is the contract itself, not the original deployer
        // (since setUp() deploys c, address(this) is the test contract, not c).
        // The deployer is address(this) (the test contract). The reference returns address(this); the mutant returns address(c).
        // We verify that owner() always equals the known deployer (address(this)), which holds for the reference
        // but fails for the mutant (because address(c) != address(this) as long as c is deployed at a different address).
        assertEq(c.owner(), address(this));
    }
}

