// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // newOwner can be any address except zero which Ownable.transferOwnership rejects
        vm.assume(newOwner != address(0));

        // Record original owner before transfer
        address origOwner = c.owner();

        // Execute transfer; will only succeed if origOwner is the stored owner
        vm.prank(origOwner);
        c.transferOwnership(newOwner);

        // After renounce (setting owner to address(0)), owner() must return 0 if stored correctly.
        // But transfer success requires origOwner matches internal _owner.
        // The bug breaks this because the internal _owner was actually set to origOwner at construction,
        // while the mutant owner() returns a constant. So the prank from origOwner works (internal _owner is origOwner),
        // but after transfer, calling owner() will still return the constant, not newOwner.
        assertEq(c.owner(), newOwner);
    }
}
